"""Algorithm 1 - Pair-graph decision procedure for cycle-bijectivity."""

from __future__ import annotations

from itertools import product
from typing import Dict, List, Optional, Tuple

Rule = Dict[Tuple[int, int, int], int]
Vertex = Tuple[int, int, int, int]  # ((a, b), (a', b')) flattened


def pair_graph(rule: Rule, q: int) -> Dict[Vertex, List[Vertex]]:
    """Vertices A^2 x A^2; an edge whenever two overlapping windows agree on output."""
    adj: Dict[Vertex, List[Vertex]] = {}
    for a, b, ap, bp in product(range(q), repeat=4):
        adj[(a, b, ap, bp)] = [
            (b, c, bp, cp)
            for c, cp in product(range(q), repeat=2)
            if rule[(a, b, c)] == rule[(ap, bp, cp)]
        ]
    return adj


def strongly_connected_components(adj: Dict[Vertex, List[Vertex]]) -> List[List[Vertex]]:
    """Tarjan's algorithm, iterative to avoid recursion limits."""
    index: Dict[Vertex, int] = {}
    low: Dict[Vertex, int] = {}
    on_stack: Dict[Vertex, bool] = {}
    stack: List[Vertex] = []
    result: List[List[Vertex]] = []
    counter = 0
    for root in adj:
        if root in index:
            continue
        work: List[Tuple[Vertex, int]] = [(root, 0)]
        while work:
            v, pi = work[-1]
            if pi == 0:
                index[v] = low[v] = counter
                counter += 1
                stack.append(v)
                on_stack[v] = True
            recursed = False
            for i in range(pi, len(adj[v])):
                w = adj[v][i]
                if w not in index:
                    work[-1] = (v, i + 1)
                    work.append((w, 0))
                    recursed = True
                    break
                if on_stack.get(w):
                    low[v] = min(low[v], index[w])
            if recursed:
                continue
            if low[v] == index[v]:
                comp: List[Vertex] = []
                while True:
                    w = stack.pop()
                    on_stack[w] = False
                    comp.append(w)
                    if w == v:
                        break
                result.append(comp)
            work.pop()
            if work:
                u = work[-1][0]
                low[u] = min(low[u], low[v])
    return result


def vertices_on_cycles(adj: Dict[Vertex, List[Vertex]]) -> List[Vertex]:
    """Vertices lying on a directed cycle: nontrivial components plus self-loops."""
    out: List[Vertex] = []
    for comp in strongly_connected_components(adj):
        if len(comp) > 1:
            out.extend(comp)
        else:
            v = comp[0]
            if v in adj[v]:
                out.append(v)
    return out


def is_cycle_bijective(rule: Rule, q: int) -> bool:
    """Exact decision: is the global map bijective on EVERY finite cycle?"""
    adj = pair_graph(rule, q)
    return not any(a != ap for (a, _b, ap, _bp) in vertices_on_cycles(adj))


def shortest_failing_length(rule: Rule, q: int) -> Optional[int]:
    """Length of the shortest cycle on which injectivity fails, or None if reversible.

    A collision of period p is a closed walk of length p through a vertex whose two
    words already disagree in their leading letter; breadth-first search from each
    such vertex back to itself finds the shortest one.
    """
    adj = pair_graph(rule, q)
    best: Optional[int] = None
    for source in adj:
        a, _b, ap, _bp = source
        if a == ap:
            continue
        dist = {source: 0}
        frontier = [source]
        found: Optional[int] = None
        while frontier and found is None:
            nxt: List[Vertex] = []
            for u in frontier:
                for w in adj[u]:
                    if w == source:
                        found = dist[u] + 1
                        break
                    if w not in dist:
                        dist[w] = dist[u] + 1
                        nxt.append(w)
                if found is not None:
                    break
            frontier = nxt
        if found is not None and (best is None or found < best):
            best = found
    return best

"""Algorithm 2 - Local decoder synthesis and minimal decoding width."""

from __future__ import annotations

from itertools import product
from typing import Dict, Optional, Tuple

Rule = Dict[Tuple[int, int, int], int]
Decoder = Dict[Tuple[int, ...], int]


def output_word(rule: Rule, word: Tuple[int, ...]) -> Tuple[int, ...]:
    """Outputs produced by the k windows contained in a word of length k + 2."""
    return tuple(rule[(word[i], word[i + 1], word[i + 2])]
                 for i in range(len(word) - 2))


def synthesise_decoder(rule: Rule, q: int, width: int, offset: int
                       ) -> Tuple[Optional[Decoder], Optional[Tuple[Tuple[int, ...], Tuple[int, ...]]]]:
    """Try to build a decoder of the given window width recovering cell `offset`.

    Returns (decoder, None) on success and (None, witness pair) on failure, where the
    witness is a pair of input words with identical output words but different letters
    at position `offset`.  Cost: O(q^{width+2}).
    """
    table: Decoder = {}
    seen: Dict[Tuple[int, ...], Tuple[int, ...]] = {}
    for word in product(range(q), repeat=width + 2):
        out = output_word(rule, word)
        target = word[offset]
        if out in table:
            if table[out] != target:
                return None, (seen[out], word)
        else:
            table[out] = target
            seen[out] = word
    return table, None


def minimal_decoding_width(rule: Rule, q: int, max_width: int = 6) -> Optional[Tuple[int, int]]:
    """Smallest window width admitting a decoder, together with a working offset.

    Returns None if no decoder of width at most `max_width` exists.  A rule is
    reversible on all cycles as soon as some finite width works, and the minimal
    width is the neighbourhood size of the inverse automaton.
    """
    for width in range(1, max_width + 1):
        for offset in range(width + 2):
            table, _ = synthesise_decoder(rule, q, width, offset)
            if table is not None:
                return width, offset
    return None


def verify_decoder(rule: Rule, q: int, width: int, offset: int, table: Decoder) -> bool:
    """Independent check of the decoding identity on all words of length width + 2."""
    return all(table[output_word(rule, word)] == word[offset]
               for word in product(range(q), repeat=width + 2))
